package com.bdscontrol.app;

import android.content.*;import android.net.Uri;import android.os.Build;import org.json.*;import java.io.*;import java.net.*;import java.util.*;

public final class ServerManager {
 private final MainActivity a;private final Context context;private final File root;private final ProcessManager pm=new ProcessManager();private final LogManager logs;private final RuntimeManager runtime;private final AppConfig config;private final MonitorManager monitor;private final PlayitManager playit;private volatile String state="stopped",version="",message="Готово к запуску";private long started;private volatile boolean shuttingDown;
 public ServerManager(Context c){context=c;a=(MainActivity)c;root=new File(c.getFilesDir(),"bds-runtime");root.mkdirs();logs=new LogManager(a);runtime=new RuntimeManager(c);config=new AppConfig(c);monitor=new MonitorManager(c);playit=new PlayitManager(c,runtime,logs);version=config.get("version","");installRuntime();}
 void configure(String json){config.put("config",json==null?"{}":json);}
 void installRuntime(){state="runtime";message="Подготовка Runtime...";emitState();new Thread(()->{try{String s=read(new URL(RuntimeManifest.URL));new RuntimeInstaller(context,new RuntimeInstaller.Events(){public void message(String t,String x){logs.event(t,x);}public void progress(String id,long d,long total){try{a.emit("runtimeProgress",new JSONObject().put("id",id).put("done",d).put("total",total).toString());}catch(Exception ignored){}}}).install(RuntimeManifest.parse(s));state="ready";message="Runtime готов";emitState();}catch(Exception e){state="error";message="Ошибка Runtime: "+e.getMessage();logs.event("error",message);emitState();}},"runtime-manifest").start();}
 private String read(URL u)throws Exception{HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","BDS-Control");try(InputStream in=c.getInputStream();ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[]b=new byte[8192];int n;while((n=in.read(b))>0)o.write(b,0,n);return o.toString("UTF-8");}}
 void listBdsVersions(){new Thread(()->{try{JSONObject r=new JSONObject(read(new URL("https://raw.githubusercontent.com/EndstoneMC/bedrock-server-data/v2/versions.json")));JSONArray ns=r.getJSONObject("release").getJSONArray("versions"),out=new JSONArray();for(int i=0;i<Math.min(ns.length(),30);i++){String v=ns.getString(i);try{JSONObject m=new JSONObject(read(new URL("https://raw.githubusercontent.com/EndstoneMC/bedrock-server-data/v2/release/"+v+"/metadata.json"))),l=m.getJSONObject("binary").getJSONObject("linux");out.put(new JSONObject().put("version",m.optString("version",v)).put("url",l.getString("url")).put("sha256",l.getString("sha256")));}catch(Exception ignored){}}a.emit("bdsVersions",out.toString());}catch(Exception e){logs.event("error","Список версий недоступен: "+e.getMessage());a.emit("bdsVersions","[]");}},"bds-versions").start();}
 void install(String v,String url,String expected){version=v;config.put("version",v);state="installing";message="Загрузка BDS...";emitState();new Thread(()->installArchive(v,url,expected,null),"bds-install").start();}
 void installLocal(Uri uri){new Thread(()->{try{File z=new File(root,"local-bds.zip");try(InputStream i=context.getContentResolver().openInputStream(uri);OutputStream o=new FileOutputStream(z)){byte[]b=new byte[65536];int n;while((n=i.read(b))>0)o.write(b,0,n);}installArchive("local",null,new JSONObject(config.get("config","{}")).optString("localSha",""),z);}catch(Exception e){fail("Ошибка локального ZIP: "+e);}},"bds-local").start();}
 private void installArchive(String v,String url,String expected,File local){try{File z=local;if(z==null){z=new File(root,"bds.zip");DownloadManager.download(url,z,(d,t)->progress(d,t));}String h=DownloadManager.sha256(z);if(expected==null||!h.equalsIgnoreCase(expected))throw new SecurityException("SHA-256 BDS не совпал: "+h);File s=new File(root,"server");if(s.exists())delete(s);ArchiveExtractor.zip(z,s);z.delete();File b=new File(s,"bedrock_server");if(!b.isFile()||!b.setExecutable(true,false))throw new IOException("bedrock_server не найден или не получил права запуска");File p=new File(s,"server.properties");if(!p.exists())PropertiesManager.writeDefaults(p,"Bedrock level","19132");state="installed";message="BDS установлен";logs.event("ready","BDS установлен и проверен; SHA-256="+h);emitState();}catch(Exception e){fail("Ошибка установки BDS: "+e.getMessage());}}
 private void fail(String m){state="error";message=m;logs.event("error",m);emitState();}
 private void progress(long d,long t){try{a.emit("progress",new JSONObject().put("done",d).put("total",t).toString());}catch(Exception ignored){}}
 void start(){if(pm.alive()){logs.event("info","Minecraft сервер уже запущен");return;}shuttingDown=false;state="starting";message="Запуск Box64...";emitState();new Thread(()->{try{File d=new File(root,"server"),b=new File(d,"bedrock_server");if(!b.isFile())throw new IOException("Сначала установи BDS и дождись статуса BDS установлен");if(!b.canExecute()&&!b.setExecutable(true,false))throw new IOException("bedrock_server не запускаем");if(!runtime.ready())throw new IOException(runtime.reason());Intent i=new Intent(context,ServerService.class);if(Build.VERSION.SDK_INT>=26)context.startForegroundService(i);else context.startService(i);pm.start(Arrays.asList(runtime.box64().getAbsolutePath(),b.getAbsolutePath()),d,runtime.env(d),(src,line)->logs.line(src,line));Thread.sleep(1200);if(!pm.alive())throw new IOException("BDS завершился сразу после запуска. Открой подробный лог");started=System.currentTimeMillis();state="running";message="Minecraft сервер работает";emitState();maybePlayit();watch();}catch(Exception e){pm.stop();fail("Ошибка запуска: "+e.getMessage());}},"bds-start").start();}
 private void maybePlayit(){try{JSONObject o=new JSONObject(config.get("config","{}"));if(o.optBoolean("playitAuto",false))playit.start(o.optString("playitSecret",""));}catch(Exception ignored){}}
 private void watch(){new Thread(()->{try{while(pm.alive()&&!shuttingDown)Thread.sleep(1000);if(!shuttingDown&&state.equals("running")){state="error";message="Сервер остановился. Открой подробный лог";emitState();}}catch(InterruptedException ignored){}} ,"bds-watchdog").start();}
 void stop(){shuttingDown=true;pm.stop();playit.stop();state="stopped";message="Сервер остановлен";emitState();}void restart(){stop();start();}void stopAll(){shuttingDown=true;pm.stop();playit.stop();}void sendCommand(String c){try{pm.write(c);}catch(Exception e){logs.event("error","stdin: "+e);}}
 void playitStart(String secret){if(!pm.alive()||!state.equals("running")){logs.event("error","Сначала запусти Minecraft сервер и дождись статуса: Minecraft сервер работает");return;}playit.start(secret);}void playitCommand(String line){playit.send(line);}void playitStop(){playit.stop();}
 String systemJson(){return monitor.snapshot();}String statusJson(){try{return new JSONObject().put("state",state).put("message",message).put("version",version).put("alive",pm.alive()).put("startedAt",started).put("playit",new JSONObject(playit.status())).put("runtime",new JSONObject(runtime.status())).toString();}catch(Exception e){return "{}";}}private void emitState(){a.emit("state",statusJson());}
 private void delete(File f){if(f.isDirectory()){File[]x=f.listFiles();if(x!=null)for(File y:x)delete(y);}f.delete();}
}
